const PICTOGRAMS: Record<PictogramName, (p: { className?: string }) => ReactNode> = {
  pushup: Pushup,
  finish: Finish,
  plank: Plank,
  pullup: Pullup,
  cycling: Cycling,
  core: Core,
  run: Run,
  walk: Walk,
  squat: Squat,
}

interface Props {
  name: PictogramName
  className?: string
}

/** Спортивна піктограма (оригінальні силуети, наслідують currentColor) */
export default function Pictogram({ name, className = 'h-4 w-4' }: Props) {
  const Icon = PICTOGRAMS[name]
  return <Icon className={className} />
}
